svg.script:
(() => {
  const svg = document.documentElement;
  const tooltip = document.getElementById('tooltip');
  const box = tooltip.querySelector('rect');
  const text = tooltip.querySelector('text');
  let tooltipWidth = 0;
  let tooltipHeight = 0;
  const move = event => {
    const point = svg.createSVGPoint();
    point.x = event.clientX;
    point.y = event.clientY;
    const cursor = point.matrixTransform(svg.getScreenCTM().inverse());
    const view = svg.viewBox.baseVal;
    let x = cursor.x + 12;
    let y = cursor.y + 12;
    if (x + tooltipWidth > view.x + view.width) x = cursor.x - tooltipWidth - 12;
    if (y + tooltipHeight > view.y + view.height) y = cursor.y - tooltipHeight - 12;
    tooltip.setAttribute('transform', `translate(${x} ${y})`);
  };
  const show = event => {
    text.replaceChildren();
    event.currentTarget.getAttribute('data-tooltip').split('\n').forEach((line, index) => {
      const span = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      span.setAttribute('x', '8');
      span.setAttribute('dy', index === 0 ? '0' : '16');
      span.textContent = line;
      text.appendChild(span);
    });
    const bounds = text.getBBox();
    tooltipWidth = bounds.width + 16;
    tooltipHeight = bounds.height + 12;
    box.setAttribute('width', tooltipWidth);
    box.setAttribute('height', tooltipHeight);
    tooltip.setAttribute('visibility', 'visible');
    move(event);
  };
  const hide = () => tooltip.setAttribute('visibility', 'hidden');
  document.querySelectorAll('[data-tooltip]').forEach(target => {
    target.addEventListener('pointerenter', show);
    target.addEventListener('pointermove', move);
    target.addEventListener('pointerleave', hide);
  });
})();
